insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-MA-1.1','P6-MA','P6','1.1','ห.ร.ม. และ ค.ร.น.',1,'บทที่ 1 จำนวนนับ เศษส่วน และทศนิยม','ตัวชี้วัด ค 1.1 ป.6/4–6','["ห.ร.ม. = ตัวหารร่วมที่มากที่สุด ใช้กับโจทย์ ‘แบ่งให้มากที่สุด / ตัดให้ยาวที่สุด’", "ค.ร.น. = ตัวคูณร่วมที่น้อยที่สุด ใช้กับโจทย์ ‘พบกันอีกครั้ง / เวลาตรงกัน’", "ห.ร.ม. × ค.ร.น. ของ 2 จำนวน = ผลคูณของ 2 จำนวนนั้น"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',1) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-MA-1.2','P6-MA','P6','1.2','เศษส่วนและทศนิยม',1,'บทที่ 1 จำนวนนับ เศษส่วน และทศนิยม','ตัวชี้วัด ค 1.1 ป.6/1, 6/7–6/10','["บวก/ลบเศษส่วน ทำส่วนให้เท่ากันก่อน (ใช้ ค.ร.น.)", "หารเศษส่วน = คูณด้วยส่วนกลับ", "ทศนิยม: ตั้งจุดให้ตรงกันเมื่อบวกลบ ทำตัวหารเป็นจำนวนนับเมื่อหาร"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',2) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-MA-2.1','P6-MA','P6','2.1','อัตราส่วนและมาตราส่วน',2,'บทที่ 2 อัตราส่วนและร้อยละ','ตัวชี้วัด ค 1.1 ป.6/2, 6/3, 6/11','["อัตราส่วน a : b เปรียบเทียบปริมาณ 2 ปริมาณ ลำดับสำคัญ", "อัตราส่วนที่เท่ากัน: คูณหรือหารทั้งสองตัวด้วยจำนวนเดียวกัน", "แบ่งตามอัตราส่วน: รวมส่วนก่อน แล้วหาค่าของ 1 ส่วน"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',3) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-MA-2.2','P6-MA','P6','2.2','ร้อยละ กำไร ขาดทุน ส่วนลด',2,'บทที่ 2 อัตราส่วนและร้อยละ','ตัวชี้วัด ค 1.1 ป.6/12','["ร้อยละ = ส่วนต่อร้อย  a% ของ N = a × N ÷ 100", "ส่วนลดคิดจากราคาป้าย กำไร/ขาดทุนคิดจากราคาทุน", "ราคาขาย = ทุน + กำไร หรือ ทุน − ขาดทุน"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',4) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-MA-3.1','P6-MA','P6','3.1','ความยาวรอบรูปและพื้นที่',3,'บทที่ 3 การวัดและเรขาคณิต','ตัวชี้วัด ค 2.1 ป.6/2–3, ค 2.2 ป.6/1','["สี่เหลี่ยมผืนผ้า = กว้าง × ยาว  สามเหลี่ยม = ½ × ฐาน × สูง", "สี่เหลี่ยมคางหมู = ½ × ผลบวกด้านคู่ขนาน × สูง", "วงกลม: เส้นรอบวง = 2πr  พื้นที่ = πr² (ใช้ π ≈ 22/7)"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',5) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-MA-3.2','P6-MA','P6','3.2','ปริมาตรและความจุ',3,'บทที่ 3 การวัดและเรขาคณิต','ตัวชี้วัด ค 2.1 ป.6/1, ค 2.2 ป.6/3–4','["ปริมาตรทรงสี่เหลี่ยมมุมฉาก = กว้าง × ยาว × สูง", "1 ลิตร = 1,000 ลูกบาศก์เซนติเมตร", "รูปคลี่ใช้ดูว่าพับแล้วได้รูปเรขาคณิตสามมิติแบบใด"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',6) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SC-1.1','P6-SC','P6','1.1','สารอาหารและระบบย่อยอาหาร',1,'บทที่ 1 สิ่งมีชีวิต','สาระวิทยาศาสตร์ชีวภาพ ป.6','["สารอาหาร 6 ประเภท: คาร์โบไฮเดรต โปรตีน ไขมัน วิตามิน แร่ธาตุ น้ำ", "ปาก→หลอดอาหาร→กระเพาะอาหาร→ลำไส้เล็ก→ลำไส้ใหญ่→ทวารหนัก", "ดูดซึมสารอาหารส่วนใหญ่ที่ลำไส้เล็ก ลำไส้ใหญ่ดูดน้ำ"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',7) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SC-1.2','P6-SC','P6','1.2','สิ่งมีชีวิตกับสิ่งแวดล้อม',1,'บทที่ 1 สิ่งมีชีวิต','สาระวิทยาศาสตร์ชีวภาพ ป.4–ป.5','["ห่วงโซ่อาหาร: ผู้ผลิต → ผู้บริโภค ผู้ย่อยสลายคืนธาตุอาหารสู่ดิน", "พืชสร้างอาหารเองได้ (ใช้แสง น้ำ แก๊สคาร์บอนไดออกไซด์)", "การจำแนกสัตว์: มีกระดูกสันหลัง / ไม่มีกระดูกสันหลัง"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',8) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SC-2.1','P6-SC','P6','2.1','สารและการแยกสารผสม',2,'บทที่ 2 สารและพลังงาน','สาระวิทยาศาสตร์กายภาพ ป.5–ป.6','["การหยิบออก การร่อน การใช้แม่เหล็ก: แยกของแข็งกับของแข็ง", "การรินออก การกรอง การตกตะกอน: แยกของแข็งที่ไม่ละลายออกจากของเหลว", "การระเหยแห้ง: ได้ของแข็งที่ละลายอยู่ในน้ำ เช่น เกลือ"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',9) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SC-2.2','P6-SC','P6','2.2','ไฟฟ้า แสง และเงา',2,'บทที่ 2 สารและพลังงาน','สาระวิทยาศาสตร์กายภาพ ป.6','["วงจรไฟฟ้า: แหล่งกำเนิดไฟฟ้า สายไฟ เครื่องใช้ไฟฟ้า (สวิตช์) ต้องครบวงจร", "ต่อหลอดแบบอนุกรม: หลอดหนึ่งขาด อีกหลอดดับ  แบบขนาน: หลอดอื่นยังสว่าง", "ไฟฟ้าสถิต: ประจุชนิดเดียวกันผลักกัน ต่างชนิดดูดกัน · เงาเกิดเมื่อวัตถุทึบแสงกั้นแสง"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',10) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SC-3.1','P6-SC','P6','3.1','หิน ซากดึกดำบรรพ์ และธรณีพิบัติ',3,'บทที่ 3 โลกและอวกาศ','สาระวิทยาศาสตร์โลกและอวกาศ ป.6','["หินอัคนี (แมกมาเย็นตัว) หินตะกอน (ตะกอนทับถม) หินแปร (ความร้อน+แรงดัน)", "ซากดึกดำบรรพ์มักพบในหินตะกอน บอกอดีตของสิ่งแวดล้อม", "ธรณีพิบัติ: น้ำท่วม ดินถล่ม แผ่นดินไหว สึนามิ ต้องรู้วิธีป้องกันตัว"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',11) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SC-3.2','P6-SC','P6','3.2','ลมฟ้าอากาศและปรากฏการณ์ทางดาราศาสตร์',3,'บทที่ 3 โลกและอวกาศ','สาระวิทยาศาสตร์โลกและอวกาศ ป.5–ป.6','["ลมทะเลพัดตอนกลางวัน (ทะเล→ฝั่ง) ลมบกพัดตอนกลางคืน (ฝั่ง→ทะเล)", "มรสุมตะวันตกเฉียงใต้ทำให้ฝนตกมาก มรสุมตะวันออกเฉียงเหนือทำให้หนาวและแห้ง", "สุริยุปราคา: ดวงจันทร์อยู่ระหว่างโลกกับดวงอาทิตย์  จันทรุปราคา: โลกอยู่ตรงกลาง"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',12) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-EN-1.1','P6-EN','P6','1.1','คำศัพท์ในชีวิตประจำวัน',1,'บทที่ 1 Vocabulary คำศัพท์','สาระภาษาเพื่อการสื่อสาร ป.4–ป.6','["หมวดคำ: ครอบครัว อาชีพ สถานที่ อาหาร สัตว์ เวลา อากาศ", "คำตรงข้าม (opposites) และคำที่หมายถึงสิ่งเดียวกัน", "ดูบริบทในประโยคช่วยเดาความหมาย"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',13) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-EN-2.1','P6-EN','P6','2.1','Tenses กาลของกริยา',2,'บทที่ 2 Grammar ไวยากรณ์','สาระภาษาเพื่อการสื่อสาร ป.6','["Present simple: ทำเป็นประจำ (He plays…, s/es กับ he/she/it)", "Present continuous: กำลังทำ (am/is/are + V-ing)", "Past simple: ทำแล้วในอดีต (V2 เช่น went, played) · Future: will + V1"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',14) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-EN-2.2','P6-EN','P6','2.2','คำบุพบท คำสรรพนาม และการเปรียบเทียบ',2,'บทที่ 2 Grammar ไวยากรณ์','สาระภาษาเพื่อการสื่อสาร ป.5–ป.6','["in / on / at กับเวลาและสถานที่", "สรรพนาม I–me–my, he–him–his, they–them–their", "เปรียบเทียบ: -er than / more … than, ขั้นสุด the -est / the most"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',15) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-EN-3.1','P6-EN','P6','3.1','บทสนทนาในสถานการณ์ต่าง ๆ',3,'บทที่ 3 Communication & Reading การสื่อสารและการอ่าน','สาระภาษาและวัฒนธรรม / ภาษาเพื่อการสื่อสาร ป.6','["ทักทาย ขอบคุณ ขอโทษ ขออนุญาต ถามทาง ซื้อของ", "เลือกคำตอบที่สุภาพและตรงกับคำถาม", "Wh-questions: What / Where / When / Who / How much / How many"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',16) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-EN-3.2','P6-EN','P6','3.2','การอ่านจับใจความ ป้าย และประกาศ',3,'บทที่ 3 Communication & Reading การสื่อสารและการอ่าน','สาระภาษาเพื่อการสื่อสาร ป.6','["อ่านคำถามก่อน แล้วหาคำสำคัญในเรื่อง", "ป้ายเตือน: No… / Don''t… = ห้าม  Please… = โปรด", "ใจความสำคัญมักอยู่ประโยคแรกหรือประโยคสุดท้าย"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',17) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-TH-1.1','P6-TH','P6','1.1','การอ่านจับใจความ',1,'บทที่ 1 การอ่าน','สาระการอ่าน ป.6','["ใจความสำคัญ = ประโยคที่คลุมเนื้อหาทั้งหมด", "แยกข้อเท็จจริง (พิสูจน์ได้) กับความคิดเห็น (ความรู้สึก)", "ดูจุดประสงค์ของผู้เขียน: ให้ความรู้ ชักชวน เตือน ให้ความบันเทิง"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',18) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-TH-2.1','P6-TH','P6','2.1','ชนิดของคำ',2,'บทที่ 2 หลักภาษา','สาระหลักการใช้ภาษาไทย ป.6','["คำนาม คำสรรพนาม คำกริยา คำวิเศษณ์", "คำบุพบท (ใน บน ของ แก่ ด้วย) คำสันธาน (และ แต่ หรือ เพราะ)", "คำอุทาน (โอ๊ย ว้าย เอ๊ะ)"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',19) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-TH-2.2','P6-TH','P6','2.2','ประโยคและการใช้คำ',2,'บทที่ 2 หลักภาษา','สาระหลักการใช้ภาษาไทย ป.6','["ประโยค = ภาคประธาน + ภาคแสดง", "ประโยคความเดียว ความรวม (เชื่อมด้วยและ แต่ หรือ) ความซ้อน", "ลักษณนามต้องเหมาะกับคำนาม เช่น ช้าง 2 เชือก"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',20) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-TH-2.3','P6-TH','P6','2.3','การสะกดคำและคำราชาศัพท์',2,'บทที่ 2 หลักภาษา','สาระหลักการใช้ภาษาไทย ป.5–ป.6','["คำที่มักเขียนผิด เช่น ผลัด/ผัด สังเกต อนุญาต", "ราชาศัพท์: เสวย (กิน) บรรทม (นอน) ประทับ (นั่ง/อยู่) พระราชดำรัส (คำพูด)", "คำสุภาพ: ศีรษะ (หัว) รับประทาน (กิน)"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',21) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-TH-3.1','P6-TH','P6','3.1','สำนวน สุภาษิต และคำพังเพย',3,'บทที่ 3 วรรณคดีและสำนวน','สาระวรรณคดีและวรรณกรรม ป.6','["สำนวนมีความหมายแฝง ไม่แปลตรงตัว", "ดูสถานการณ์ในโจทย์แล้วเลือกสำนวนที่ตรงความหมาย", "สุภาษิตเป็นคำสอน เช่น น้ำหยดลงหินทุกวัน หินมันยังกร่อน"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',22) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SO-1.1','P6-SO','P6','1.1','ศาสนา ศีลธรรม จริยธรรม',1,'บทที่ 1 ศาสนาและหน้าที่พลเมือง','สาระศาสนา ศีลธรรม จริยธรรม ป.6','["พระรัตนตรัย: พระพุทธ พระธรรม พระสงฆ์", "อริยสัจ 4: ทุกข์ สมุทัย นิโรธ มรรค · เบญจศีล 5 ข้อ", "วันสำคัญ: วิสาขบูชา มาฆบูชา อาสาฬหบูชา"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',23) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SO-1.2','P6-SO','P6','1.2','หน้าที่พลเมืองและการปกครอง',1,'บทที่ 1 ศาสนาและหน้าที่พลเมือง','สาระหน้าที่พลเมือง วัฒนธรรม และการดำเนินชีวิตในสังคม ป.6','["ประเทศไทยปกครองระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข", "อำนาจอธิปไตย 3 ฝ่าย: นิติบัญญัติ บริหาร ตุลาการ", "สิทธิ หน้าที่ และการเคารพกฎหมาย กติกาของสังคม"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',24) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SO-2.1','P6-SO','P6','2.1','การผลิต การบริโภค และเศรษฐกิจพอเพียง',2,'บทที่ 2 เศรษฐศาสตร์','สาระเศรษฐศาสตร์ ป.6','["ผู้ผลิต ผู้บริโภค สินค้าและบริการ", "ปรัชญาของเศรษฐกิจพอเพียง: พอประมาณ มีเหตุผล มีภูมิคุ้มกัน", "สหกรณ์ การออม และการใช้เงินอย่างฉลาด"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',25) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SO-3.1','P6-SO','P6','3.1','ประวัติศาสตร์ไทย',3,'บทที่ 3 ประวัติศาสตร์และภูมิศาสตร์','สาระประวัติศาสตร์ ป.4–ป.6','["สมัยสุโขทัย อยุธยา ธนบุรี รัตนโกสินทร์", "บุคคลสำคัญ: พ่อขุนรามคำแหงฯ สมเด็จพระนเรศวรฯ สมเด็จพระเจ้าตากสินฯ", "รู้จักใช้ศักราช: พ.ศ. = ค.ศ. + 543"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',26) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,indicators,concepts,source,status,sort) values ('P6-SO-3.2','P6-SO','P6','3.2','ภูมิศาสตร์ไทยและอาเซียน',3,'บทที่ 3 ประวัติศาสตร์และภูมิศาสตร์','สาระภูมิศาสตร์ ป.6','["ภาคของไทย ภูมิประเทศ และภูมิอากาศ", "แผนที่: ทิศ มาตราส่วน สัญลักษณ์ เส้นละติจูด/ลองจิจูด", "ประเทศสมาชิกอาเซียน เมืองหลวง และความร่วมมือ"]'::jsonb,'live ป.6 CURRICULUM (kruom-xexamgym-p6)','live',27) on conflict (id) do update set name_th=excluded.name_th, group_no=excluded.group_no, group_name=excluded.group_name, indicators=excluded.indicators, concepts=excluded.concepts;
